const backend = $('API BR backend').all().map(i => i.json) || [];
const frontend = $('API BR frontend').all().map(i => i.json) || [];
const mobile = $('API BR mobile').all().map(i => i.json) || [];

const todas = [...backend, ...frontend, ...mobile];

const KEYWORDS_NIVEL = ['júnior', 'junior', 'jr', 'estágio', 'estagio', 'trainee', 'iniciante', 'entry'];
const KEYWORDS_TECH = ['python', 'javascript', 'java', 'react', 'node', 'typescript', 'php', 'kotlin', 'swift'];

const vagasFiltradas = todas
  .filter(v => {
    const texto = (v.title + ' ' + v.body + ' ' + (v.labels || []).join(' ')).toLowerCase();
    const ehIniciante = KEYWORDS_NIVEL.some(k => texto.includes(k));
    const temTech = KEYWORDS_TECH.some(k => texto.includes(k));
    return ehIniciante || temTech;
  })
  .map(v => {
    const texto = (v.title + ' ' + v.body + '').toLowerCase();

    const techs = [];
    if (texto.includes('python')) techs.push('Python');
    if (texto.includes('javascript') || texto.includes(' js ')) techs.push('JavaScript');
    if (texto.includes('java') && !texto.includes('javascript')) techs.push('Java');
    if (texto.includes('react')) techs.push('React');
    if (texto.includes('node')) techs.push('Node.js');
    if (texto.includes('typescript')) techs.push('TypeScript');
    if (texto.includes('php')) techs.push('PHP');

    let tipo = 'pleno';
    if (texto.includes('júnior') || texto.includes('junior') || texto.includes(' jr ')) tipo = 'junior';
    if (texto.includes('estágio') || texto.includes('estagio')) tipo = 'estagio';
    if (texto.includes('trainee')) tipo = 'trainee';

    const remoto = texto.includes('remoto') || texto.includes('remote') || texto.includes('home office');

    let cidade = 'Brasil';
    const cidadeMatch = v.title?.match(/\b(São Paulo|Rio de Janeiro|Belo Horizonte|Curitiba|Porto Alegre|Recife|Salvador|Fortaleza|Manaus|Brasília|Florianópolis|Campinas|Remoto)\b/i);
    if (cidadeMatch) cidade = cidadeMatch[1];
    if (remoto) cidade = 'Remoto';

    return {
      titulo: v.title || 'Vaga de Desenvolvedor',
      empresa: v.user?.login || 'Empresa',
      cidade,
      remoto,
      tipo,
      tecnologias: techs,
      descricao: (v.body || '').substring(0, 500),
      url: v.html_url || v.url || '#',
      fonte: 'apibr',
      publicada_em: v.created_at || new Date().toISOString()
    };
  })
  .slice(0, 50);

return vagasFiltradas.map(v => ({ json: v }));

